import { defineComponent } from 'vue';
import confetti from 'canvas-confetti';
import { PrizeLeagueManager } from '../../../services/prize-league/prize-league-manager';
import { ITournamentHistoryEntry } from '../../../services/prize-league/types';
import { getPrizeLeagueManager } from '../prize-league-utils';
import { device } from '../../../services/device';
import { inversifyContainer } from '../../../inversify/container';
import { getEndpoints } from '../../../endpoints/endpoints';

export default defineComponent({
    name: 'PrizeLeagueOverlays',
    props: {
        showInfo: {
            type: Boolean,
            default: false
        }
    },
    emits: ['dismissed', 'close-info'],
    computed: {
        prizeLeagueManager(): PrizeLeagueManager {
            return getPrizeLeagueManager();
        },
        isCalculatingResults(): boolean {
            return this.prizeLeagueManager.isCalculatingResults.value;
        },
        tournamentResult(): ITournamentHistoryEntry | null {
            return this.prizeLeagueManager.tournamentResult.value;
        },
        resultPrizeText(): string {
            return this.prizeLeagueManager.resultPrizeText.value;
        },
        resultDidNotSpin(): boolean {
            return this.prizeLeagueManager.resultDidNotSpin.value;
        },
        isJoining(): boolean {
            return this.prizeLeagueManager.isJoining.value;
        },
        joinResult(): string | null {
            return this.prizeLeagueManager.joinResult.value;
        },
        translations() {
            return inversifyContainer.strings.prizeLeague;
        }
    },
    watch: {
        tournamentResult(newResult: ITournamentHistoryEntry | null) {
            if (newResult && this.prizeLeagueManager.resultShouldShowConfetti.value) {
                this.triggerConfetti();
            }
        }
    },
    methods: {
        onBackdropClick() {
            // Dismiss info overlay if showing
            if (this.showInfo) {
                this.$emit('close-info');
                return;
            }

            // Only dismiss if showing results (not calculating)
            if (!this.isCalculatingResults && this.tournamentResult) {
                this.dismissResults();
            }
        },
        closeInfo() {
            this.$emit('close-info');
        },
        triggerConfetti() {
            // Fire confetti with arcade theme colors
            const colors = ['#D579FF', '#B9FF9C', '#FFEE58', '#FF6EC7', '#9538BE'];
            
            // Dual cannons with crossing paths
            const duration = 500;
            const end = Date.now() + duration;

            // Detect device type for positioning
            const isDesktop = device.type.isDesktop;
            
            // Desktop: cannons in bottom-right area (action menu is on right)
            // Mobile: cannons at bottom corners (action menu is centered bottom)
            const leftCannon = isDesktop ? { x: 0.75, y: 1 } : { x: 0, y: 1 };
            const rightCannon = isDesktop ? { x: 1, y: 1 } : { x: 1, y: 1 };
            // These angles are counterintuitive, don't ask me why
            const leftAngle = isDesktop ? 75 : 75;
            const rightAngle = isDesktop ? 105 : 105;

            const frame = () => {
                // Left cannon shoots right
                confetti({
                    particleCount: 4,
                    angle: leftAngle,
                    spread: 30,
                    origin: leftCannon,
                    colors: colors,
                    startVelocity: 45,
                    gravity: 1.2,
                    scalar: 1
                });
                
                // Right cannon shoots left
                confetti({
                    particleCount: 4,
                    angle: rightAngle,
                    spread: 30,
                    origin: rightCannon,
                    colors: colors,
                    startVelocity: 45,
                    gravity: 1.2,
                    scalar: 1
                });

                if (Date.now() < end) {
                    requestAnimationFrame(frame);
                }
            };

            frame();
        },
        dismissResults() {
            this.prizeLeagueManager.clearResultsState();
            this.prizeLeagueManager.clearCurrentlyViewedTournament();
            this.prizeLeagueManager.checkForActiveTournament();
            this.$emit('dismissed');
        },
        placedText(): string {
            if (!this.tournamentResult) return '';
            return this.translations.results.placed.replace('{{position}}', this.tournamentResult.user.positionDisplay);
        },
        wonText(): string {
            if (!this.resultPrizeText) return '';
            return this.translations.results.won.replace('{{prize}}', this.resultPrizeText);
        },
        termsAndConditionsClicked() {
            inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'navigation', data: { type: 'url', location: getEndpoints().prizeLeagueTandCs } });
        }
    }
});
